\set ON_ERROR_STOP on
\echo 'PRECHECK ONLY — NO DATABASE CHANGES'
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path = ahdah, pg_catalog;
DO $preflight$
DECLARE actual text;
BEGIN
 IF current_database()<>'ahdah_db' THEN RAISE EXCEPTION 'Wrong database'; END IF;
 IF current_setting('server_version_num')::integer NOT BETWEEN 180000 AND 189999 THEN RAISE EXCEPTION 'Requires reviewed PostgreSQL 18 baseline'; END IF;
 IF to_regnamespace('ahdah') IS NULL THEN RAISE EXCEPTION 'Missing ahdah schema'; END IF;
 IF to_regprocedure('pg_catalog.gen_random_uuid()') IS NULL OR to_regprocedure('pg_catalog.sha256(bytea)') IS NULL THEN RAISE EXCEPTION 'Required built-in function absent'; END IF;
 IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ahdah' AND c.relkind IN ('r','p'))<>91 THEN RAISE EXCEPTION 'Baseline must have 91 tables'; END IF;
 SELECT (WITH objects AS (
 SELECT c.oid,c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ahdah' AND c.relkind IN ('r','p')
), signatures AS (
 SELECT 'column|'||c.relname||'|'||a.attname||'|'||format_type(a.atttypid,a.atttypmod)||'|'||a.attnotnull::text||'|'||coalesce(pg_get_expr(d.adbin,d.adrelid),'')||'|'||a.attgenerated::text||'|'||a.attidentity::text s
 FROM objects c JOIN pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT 'constraint|'||c.relname||'|'||k.conname||'|'||pg_get_constraintdef(k.oid)||'|'||k.convalidated::text||'|'||k.condeferrable::text FROM objects c JOIN pg_constraint k ON k.conrelid=c.oid
 UNION ALL SELECT 'index|'||c.relname||'|'||pg_get_indexdef(i.indexrelid) FROM objects c JOIN pg_index i ON i.indrelid=c.oid
 UNION ALL SELECT 'trigger|'||c.relname||'|'||pg_get_triggerdef(g.oid) FROM objects c JOIN pg_trigger g ON g.tgrelid=c.oid WHERE NOT g.tgisinternal
 UNION ALL SELECT 'function|'||p.proname||'|'||pg_get_functiondef(p.oid) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='ahdah'
) SELECT md5(string_agg(s,E'\n' ORDER BY s COLLATE "C")) FROM signatures) INTO actual;
 IF actual <> 'd697e4fbc6699faed6076d576a814d38' THEN RAISE EXCEPTION 'Catalog fingerprint differs: stop and review drift'; END IF;
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ahdah' AND c.relname IN ('project_financial_controls','project_custody_positions','custody_operations','custody_movement_entries','custody_reservations','project_settlements','project_settlement_snapshots','project_settlement_snapshot_categories','project_settlement_events','project_closure_certificates','project_reopenings','project_authorization_decisions','project_operational_events','settlement_policy_versions','company_settlement_policy_bindings','document_custody_events','document_policy_exceptions','verified_evidence_objects','project_owner_reconciliations','project_owner_reconciliation_positions','project_owner_retention_items','financial_resolution_effects','supplier_credit_intents','supplier_credit_intent_applications','legacy_attribution_reviews','legacy_attribution_review_projects','ix_t01_state','ix_t02_project_balance','ix_t04_position_time','ux_t05_expense_allocation','ux_t05_transfer_allocation','ix_t05_position_status','ix_t06_workflow','ix_t07_revision','ix_t16_evidence_time','ux_t17_supersedes','ix_t19_workflow','ux_t22_expense_return_id','ux_t22_advance_settlement_resolution_id','ux_t22_custody_movement_entry_id','ux_t22_funding_source_ledger_entry_id','ux_t22_personal_claim_adjustment_id','ux_t22_personal_claim_write_off_id','ux_t22_supplier_debt_write_off_id','ux_t22_supplier_credit_note_id','ux_t24_reversal','ix_t26_impact','ix_t01_fk_active_settlement_id','ix_t01_fk_active_closure_id','ix_t03_fk_requested_by_user_id','ix_t03_fk_approved_by_user_id','ix_t03_fk_authorization_decision_id','ix_t03_fk_source_operation_id','ix_t03_fk_money_transfer_id','ix_t03_fk_expense_id','ix_t03_fk_expense_return_id','ix_t03_fk_legacy_attribution_review_id','ix_t04_fk_balance_ledger_entry_id','ix_t04_fk_reverses_entry_id','ix_t04_fk_actor_user_id','ix_t05_fk_custody_operation_id','ix_t05_fk_expense_advance_allocation_id','ix_t05_fk_transfer_advance_allocation_id','ix_t05_fk_resolved_by_operation_id','ix_t06_fk_previous_settlement_id','ix_t06_fk_policy_version_id','ix_t06_fk_prepared_by_user_id','ix_t06_fk_submitted_by_user_id','ix_t06_fk_approved_by_user_id','ix_t06_fk_snapshot_id','ix_t07_fk_policy_version_id','ix_t07_fk_evaluated_by_user_id','ix_t08_fk_snapshot_id','ix_t09_fk_settlement_id','ix_t09_fk_actor_user_id','ix_t09_fk_authorization_decision_id','ix_t09_fk_snapshot_id','ix_t10_fk_project_settlement_id','ix_t10_fk_approved_snapshot_id','ix_t10_fk_closure_snapshot_id','ix_t10_fk_policy_version_id','ix_t10_fk_closed_by_user_id','ix_t10_fk_authorization_decision_id','ix_t11_fk_previous_closure_id','ix_t11_fk_new_settlement_id','ix_t11_fk_actor_user_id','ix_t11_fk_authorization_decision_id','ix_t11_fk_audit_log_id','ix_t12_fk_actor_user_id','ix_t12_fk_policy_version_id','ix_t12_fk_preparer_user_id','ix_t12_fk_submitter_user_id','ix_t12_fk_beneficiary_user_id','ix_t12_fk_evidence_id','ix_t13_fk_actor_user_id','ix_t13_fk_evidence_id','ix_t13_fk_acknowledgment_event_id','ix_t13_fk_authorization_decision_id','ix_t14_fk_approved_by_user_id','ix_t14_fk_predecessor_id','ix_t15_fk_active_policy_version_id','ix_t15_fk_activated_by_user_id','ix_t16_fk_evidence_id','ix_t16_fk_expense_document_id','ix_t16_fk_actor_user_id','ix_t16_fk_policy_version_id','ix_t16_fk_previous_event_id','ix_t16_fk_authorization_decision_id','ix_t17_fk_evidence_id','ix_t17_fk_expense_document_id','ix_t17_fk_policy_version_id','ix_t17_fk_approved_by_user_id','ix_t17_fk_authorization_decision_id','ix_t17_fk_supersedes_exception_id','ix_t18_fk_project_id','ix_t18_fk_expense_document_id','ix_t18_fk_verified_by_user_id','ix_t18_fk_source_evidence_id','ix_t19_fk_policy_version_id','ix_t19_fk_prepared_by_user_id','ix_t19_fk_approved_by_user_id','ix_t19_fk_evidence_id','ix_t19_fk_supersedes_id','ix_t20_fk_owner_reconciliation_id','ix_t21_fk_owner_position_id','ix_t21_fk_evidence_id','ix_t21_fk_approved_by_user_id','ix_t22_fk_expense_return_id','ix_t22_fk_advance_s