ct','pk_t22','uq_t22_tenant','uq_t22_project','uq_t22_economic_key','pk_t23','uq_t23_tenant','uq_t23_project','pk_t24','uq_t24_tenant','uq_t24_application','pk_t25','uq_t25_tenant','uq_t25_source','pk_t26','uq_t26_tenant','uq_t26_project','uq_t26_review_project')) THEN RAISE EXCEPTION 'Conflicting proposed relation/index name'; END IF;
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='ahdah' AND p.proname IN ('settlement_advance_currency','settlement_approval_packet','settlement_category_insert','settlement_check_custody','settlement_child_freeze','settlement_control_check','settlement_custody_authority','settlement_fixed_keys','settlement_freeze_status','settlement_owner_approval','settlement_packet_check')) THEN RAISE EXCEPTION 'Conflicting proposed function name'; END IF;
END $preflight$;
ROLLBACK;
\echo 'Baseline metadata matches; this is not execution approval.'
